function unobfuscate(e,t){document.getElementById(e).innerHTML=rot13(t)}function rot13(e){return e.replace(/[a-z]/gi,e=>"NOPQRSTUVWXYZABCDEFGHIJKLMnopqrstuvwxyzabcdefghijklm"["ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz".indexOf(e)])}function enableEmailButtons(){document.querySelectorAll(".email-link").forEach(e=>{e.addEventListener("click",()=>{const t=e.dataset.email;if(!t)return;window.location.href=`mailto:${rot13(t)}`})})}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",enableEmailButtons):enableEmailButtons()